class Node:
    """A node in a binary search tree."""

    def __init__(self, key):
        """Initializes a new node with the given key."""
        self.left = None
        self.right = None
        self.val = key

    def insert(self, key):
        """Inserts a new node with the given key in the correct position."""
        if not self.val:
            self.val = key
        elif key < self.val:
            if self.left:
                self.left.insert(key)
            else:
                self.left = Node(key)
        else:
            if self.right:
                self.right.insert(key)
            else:
                self.right = Node(key)

    def inorder_traversal(self):
        """Returns a list of values in the tree in ascending order."""
        result = []
        if self.left:
            result += self.left.inorder_traversal()
        result.append(self.val)
        if self.right:
            result += self.right.inorder_traversal()
        return result


def construct_bst(nums):
    """Constructs a binary search tree from a list of integers."""
    if not nums:
        return None
    mid = len(nums) // 2
    root = Node(nums[mid])
    root.left = construct_bst(nums[:mid])
    root.right = construct_bst(nums[mid + 1:])
    return root


if __name__ == "__main__":
    nums = [1, 2, 3, 4, 5, 6, 7]
    bst = construct_bst(nums)
    print("Inorder traversal of the constructed BST:")
    print(bst.inorder_traversal())
```

This program defines a `Node` class for the binary search tree and two functions: `construct_bst` and `inorder_traversal`. The `construct_bst` function constructs a binary search tree from a list of integers, and the `inorder_traversal` function returns a list of values in the tree in ascending order. The main part of the code demonstrates how to use these functions to construct a binary search tree from a list of integers and print the inorder traversal of the constructed tree.

