def update_nested_dict(d, old_val, new_val):
    """
    Recursively update the values in a nested dictionary.

    Args:
        d (dict): The nested dictionary to update.
        old_val: The value to replace.
        new_val: The new value to use.

    Returns:
        dict: The updated nested dictionary.
    """
    if isinstance(d, dict):
        return {
            key: update_nested_dict(val, old_val, new_val)
