Below is a Python script that generates a tree representation for a given array of numbers using the binary tree concept. This script uses the `BinaryTree` class to represent the binary tree and the `array_to_tree` function to convert the given array into a binary tree.

```python
class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert_recursive(self.root, key)

    def _insert_recursive(self, node, key):
        if key < node.val:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert_recursive(node.left, key)
        else:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert_recursive(node.right, key)

    def print_tree(self):
        if self.root:
            self._print_tree_recursive(self.root)
            print()

    def _print_tree_recursive(self, node, level=0):
        if node:
            self._print_tree_recursive(node.right, level + 1)
            print(' '* level + str(node.val))
            self._print_tree_recursive(node.left, level + 1)

def array_to_tree(arr):
    if not arr:
        return None

    mid = len(arr) // 2
    tree = BinaryTree()
    tree.insert(arr[mid])

    left_subtree = array_to_tree(arr[:mid])
    right_subtree = array_to_tree(arr[mid + 1:])

    if left_subtree:
        tree.root.left = left_subtree.root

    if right_subtree:
        tree.root.right = right_subtree.root

    return tree

# Example usage
