To solve a Sudoku puzzle, we can use a backtracking algorithm. The algorithm works by filling each cell of the grid one by one, and for each cell, it tries to fill the cell with digits from 1 to 9. If the current value leads to an invalid Sudoku solution, it backtracks and tries the next value.

Here's the Python code to solve a Sudoku puzzle using the backtracking algorithm:

```python
def is_valid(grid, row, col, num):
    """Check if the given number can be placed at the specified position in the grid."""
    # Check the row
    for i in range(9):
        if grid[row][i] == num:
            return False
    # Check the column
    for i in range(9):
        if grid[i][col] == num:
            return False
    # Check the 3x3 box
    box_row = row - row % 3
    box_col = col - col % 3
    for i in range(3):
        for j in range(3):
            if grid[i + box_row][j + box_col] == num:
                return False
    return True


def solve_sudoku(grid):
    """Solve a Sudoku puzzle using the backtracking algorithm."""
    for row in range(9):
        for col in range(9):
            if grid[row][col] == 0:
                # Try numbers from 1 to 9
                for num in range(1, 10):
                    if is_valid(grid, row, col, num):
                        # Place the number in the grid
                        grid[row][col] = num
                        # Recursively solve the rest of the puzzle
                        if solve_sudoku(grid):
                            return True
                        # If the recursive call fails, backtrack and try the next number
                        grid[row][col] = 0
                return False
    return True


def print_grid(grid):
    """Print the Sudoku grid."""
    for row in grid:
        for cell in row:
            print(cell, end=" ")
        print()


# Example usage
grid = [
    [3, 0, 6, 5, 0, 8, 4, 0, 0],
    [5, 2, 0, 0, 0, 0, 0, 0, 0],
    [0, 8, 7, 0, 0, 0, 0, 3, 1],
    [0, 0, 3, 0, 1, 0, 0, 8, 0],
    [9, 0, 0, 8, 6, 3, 0, 0, 5],
