import spacy
import random

# Load the English language model
nlp = spacy.load("en_core_web_sm")

# Define intents and responses
intents = {
    "greet": ["hi", "hello", "hey"],
    "goodbye": ["bye", "goodbye", "see you later"],
    "thanks": ["thanks", "thank you", "no problem"],
}

responses = {
    "greet": ["Hello!", "Hi there!", "Hey, how can I help you?"],
    "goodbye": ["Goodbye!", "See you later!", "Have a nice day!"],
    "thanks": ["You're welcome!", "No problem at all!", "My pleasure!"],
}

# Define a function to extract the intent from the user's message
def get_intent(message):
    doc = nlp(message)
    intents_found = []

    for intent_name, patterns in intents.items():
        for token in doc:
            if token.text.lower() in patterns:
                intents_found.append(intent_name)

    if not intents_found:
        return None

    return random.choice(intents_found)


# Define a function to generate a response based on the detected intent
def generate_response(intent):
    if intent is None:
        return random.choice(responses["greet"])

    response_list = responses.get(intent)

    if response_list is None:
        return random.choice(responses["greet"])

    return random.choice(response_list)


# Define the main chatbot function
def chatbot():
    print("Welcome to the Chatbot!")
    while True:
        message = input("\nYou: ")

        if message.lower() == "exit":
            print(random.choice(responses["goodbye"]))
            break

        intent = get_intent(message)
        response = generate_response(intent)
        print(f"Chatbot: {response}")


# Run the chatbot
chatbot()
```

