def is_valid(grid, row, col, num):
    """Check if a number is valid in the given cell."""
    for x in range(9):
        if grid[row][x] == num or grid[x][col] == num:
            return False

    start_row = row - row % 3
    start_col = col - col % 3

    for i in range(3):
        for j in range(3):
            if grid[i + start_row][j + start_col] == num:
                return False

    return True


def solve_sudoku(grid):
    """Solve the Sudoku puzzle using backtracking."""
    for row in range(9):
        for col in range(9):
            if grid[row][col] == 0:
                for num in range(1, 10):
                    if is_valid(grid, row, col, num):
                        grid[row][col] = num
                        if solve_sudoku(grid):
                            return True
                        grid[row][col] = 0  # backtrack
                return False
    return True


def print_grid(grid):
    """Print the Sudoku grid in a user-friendly format."""
    for row in grid:
        for cell in row:
            print(f"{cell} ", end="")
        print()


