        self.side = side

    def calculate_area(self):
        return self.side ** 2


class Triangle(Shape):
    def __init__(self, base, height, side1, side2):
        self.base = base
        self.height = height
        self.side1 = side1
        self.side2 = side2

    def calculate_area(self):
        s = (self.base + self.height + self.side1 + self.side2) / 2
        return (s * (s - self.base) * (s - self.height) * (s - self.side1) * (s - self.side2)) ** 0.5


class Rectangle(Shape):
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def calculate_area(self):
        return self.length * self.width
